/**
 * Unit tests for CategoryPlot.getRangeAxisIndex
 */
public class CategoryPlot_getRangeAxisIndex_TriageGen2Test {

    private CategoryPlot categoryPlot;

    @Before
    public void setUp() {
        categoryPlot = new CategoryPlot();
    }

    /**
     * Test case 1: The axis is found directly in the categoryPlot's rangeAxes.
     * This covers the path where result >= 0.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInLocalRangeAxes() {
        ValueAxis axis1 = mock(ValueAxis.class);
        ValueAxis axis2 = mock(ValueAxis.class);

        categoryPlot.setRangeAxes(new ValueAxis[]{axis1, axis2});

        int index = categoryPlot.getRangeAxisIndex(axis2);

        assertEquals("Should return the correct index from local range axes", 1, index);
    }

    /**
     * Test case 2: The axis is NOT in the categoryPlot's rangeAxes, 
     * and the parent is NOT a CategoryPlot.
     * This covers the 'result < 0' branch and the 'parent instanceof CategoryPlot' being false.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInLocalAndParentNotCategoryPlot() {
        ValueAxis axis = mock(ValueAxis.class);

        // Create a dummy Plot that is NOT a CategoryPlot to act as parent
        // We use a mock of Plot (the base class)
        Plot dummyParent = mock(Plot.class);

        // In JFreeChart, the relationship is usually managed via Chart -> Plot.
        // However, since we cannot easily inject a parent into a Plot via public API 
        // without a Chart, we rely on the fact that if getParent() returns null, 
        // the instanceof check fails.

        // Default categoryPlot.getParent() is null.
        int index = categoryPlot.getRangeAxisIndex(axis);

        assertEquals("Should return -1 when not found locally and no parent exists", -1, index);
    }

    /**
     * Test case 3: The axis is NOT in the categoryPlot's rangeAxes,
     * but the parent IS a CategoryPlot.
     * This covers the 'result < 0' branch and the 'parent instanceof CategoryPlot' being true.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInLocalButFoundInParentCategoryPlot() {
        // We need to simulate a hierarchy where categoryPlot.getParent() returns another CategoryPlot
        // Since we cannot easily mock the 'getParent' method of the real class because it's not virtual/overridable 
        // in a way that allows easy mocking of the internal call, we use a spy or a subclass if necessary.
        // However, in standard JFreeChart, a Plot's parent is a Chart. 
        // But the logic specifically checks if parent instanceof CategoryPlot.

        // To achieve high coverage on the specific branch:
        // if (parent instanceof CategoryPlot) { result = p.getRangeAxisIndex(axis); }

        CategoryPlot parentPlot = new CategoryPlot();
        ValueAxis parentAxis = mock(ValueAxis.class);
        parentPlot.setRangeAxis(parentAxis);

        // We create a subclass to override getParent to return our parentPlot
        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return parentPlot;
            }
        };

        ValueAxis targetAxis = mock(ValueAxis.class); // Not in child, but in parent

        int index = childPlot.getRangeAxisIndex(targetAxis);

        assertEquals("Should delegate to parent's getRangeAxisIndex", 0, index);
    }

    /**
     * Test case 4: The axis is NOT in the categoryPlot's rangeAxes, 
     * the parent IS a CategoryPlot, but the axis is NOT in the parent either.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInLocalAndNotFoundInParent() {
        CategoryPlot parentPlot = new CategoryPlot();

        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return parentPlot;
            }
        };

        ValueAxis axis = mock(ValueAxis.class);

        int index = childPlot.getRangeAxisIndex(axis);

        assertEquals("Should return -1 if not found in child and not found in parent", -1, index);
    }
}
